// notice: 通知公告 (sys_notices). Generated by cmd/gen, then extended with
// publish/revoke (publish.go) and the inbox (inbox.go).

const noticeTable = "sys_notices"

// noticeScope isolates rows by data scope (design doc 7.3).
var noticeScope = datascope.Spec{OwnerColumn: "t.created_by"}

var noticePermissions = []perm.Def{
	{Code: "notice:notice:view", Name: "查看通知公告", Menu: "notice.notice"},
	{Code: "notice:notice:create", Name: "新增通知公告", Menu: "notice.notice"},
	{Code: "notice:notice:update", Name: "编辑通知公告", Menu: "notice.notice"},
	{Code: "notice:notice:delete", Name: "删除通知公告", Menu: "notice.notice"},
	{Code: permNoticePublish, Name: "发布/撤回通知公告", Menu: "notice.notice"},
}

var noticeMenus = []menu.Def{
	{
		Code: "notice.notice", Parent: "notice.root", Type: menu.TypeMenu, Title: "通知公告",
		Path: "/notice/notice", Component: "notice/notice/index", Permission: "notice:notice:view",
		Icon: "ri:file-list-3-line", Sort: 1,
	},
}

func (m *Module) noticeRoutes(r *module.Router) {
	g := r.Group("/notices")
	g.GET("", access.Perm("notice:notice:view"), handle(m.listNotices)).Doc(module.Doc{Summary: "通知公告列表", Query: noticeFilter{}, Response: httpx.Page[noticeView]{}})
	g.GET("/:id", access.Perm("notice:notice:view"), handle(m.getNotice)).Doc(module.Doc{Summary: "通知公告详情", Response: noticeView{}})
	g.POST("", access.Perm("notice:notice:create"), handle(m.createNotice)).Doc(module.Doc{Summary: "新增通知公告", Body: noticeRequest{}, Response: noticeView{}})
	g.PUT("/:id", access.Perm("notice:notice:update"), handle(m.updateNotice)).Doc(module.Doc{Summary: "编辑通知公告", Body: noticeRequest{}, Response: noticeView{}})
	g.DELETE("/:id", access.Perm("notice:notice:delete"), handle(m.deleteNotice)).Doc(module.Doc{Summary: "删除通知公告"})
	g.POST("/:id/publish", access.Perm(permNoticePublish), handle(m.publishNotice)).Doc(module.Doc{Summary: "发布通知公告", Description: "发布后所有用户可见，并重新计为未读", Body: versionRequest{}, Response: noticeView{}})
	g.POST("/:id/revoke", access.Perm(permNoticePublish), handle(m.revokeNotice)).Doc(module.Doc{Summary: "撤回通知公告", Description: "撤回后变为草稿，用户不再看到", Body: versionRequest{}, Response: noticeView{}})
}

type noticeView struct {
	ID          ids.ID           `json:"id" doc:"ID"`
	Title       string           `json:"title" doc:"标题"`
	Type        int16            `json:"type" doc:"类型"`
	Content     string           `json:"content" doc:"内容"`
	PublishedAt *time.Time       `json:"publishedAt" doc:"发布时间"`
	Attachments []attachment.Ref `json:"attachments" doc:"附件"`
	Version     int              `json:"version" doc:"版本"`
	CreatedAt   time.Time        `json:"createdAt" doc:"创建时间"`
	UpdatedAt   time.Time        `json:"updatedAt" doc:"更新时间"`
	CreatedBy   *ids.ID          `json:"createdBy" doc:"创建人"`
	UpdatedBy   *ids.ID          `json:"updatedBy" doc:"更新人"`
}

type noticeRow struct {
	ID          int64
	Title       string
	Type        int16
	Content     string
	PublishedAt *time.Time
	Attachments string
	Version     int
	CreatedAt   time.Time
	UpdatedAt   time.Time
	CreatedBy   *int64
	UpdatedBy   *int64
}

const noticeColumns = `t.id, t.title, t.type, t.content, t.published_at, t.attachments::text AS attachments, t.version, t.created_at, t.updated_at, t.created_by, t.updated_by`

func (r noticeRow) view() noticeView {
	return noticeView{
		ID:          ids.ID(r.ID),
		Title:       r.Title,
		Type:        r.Type,
		Content:     r.Content,
		PublishedAt: r.PublishedAt,
		Attachments: decodeAttachments(r.Attachments),
		Version:     r.Version,
		CreatedAt:   r.CreatedAt,
		UpdatedAt:   r.UpdatedAt,
		CreatedBy:   (*ids.ID)(r.CreatedBy),
		UpdatedBy:   (*ids.ID)(r.UpdatedBy),
	}
}

type noticeFilter struct {
	Title string `form:"title" binding:"max=128" doc:"标题（模糊匹配）"`
	Type  *int64 `form:"type" doc:"类型"`
	State string `form:"state" binding:"omitempty,oneof=draft published" doc:"状态：draft 草稿，published 已发布"`
}

// scopedNotices starts a query over the 通知公告 rows visible to the caller.
func scopedNotices(ctx context.Context, db *gorm.DB) *gorm.DB {
	q := db.WithContext(ctx).Table(noticeTable + " AS t")
	return actor.Scope(ctx, q, noticeScope)
}

func applyNoticeFilter(q *gorm.DB, f noticeFilter) *gorm.DB {
	if v := strings.TrimSpace(f.Title); v != "" {
		q = q.Where("t.title ILIKE ?", "%"+escapeLike(v)+"%")
	}
	if f.Type != nil {
		q = q.Where("t.type = ?", *f.Type)
	}
	switch f.State {
	case "draft":
		q = q.Where("t.published_at IS NULL")
	case "published":
		q = q.Where("t.published_at IS NOT NULL")
	}
	return q
}

func bindNoticeFilter(c *gin.Context) (noticeFilter, error) {
	var f noticeFilter
	if err := c.ShouldBindQuery(&f); err != nil {
		return f, httpx.BadRequest("查询参数错误").WithCause(err)
	}
	return f, nil
}

func (m *Module) listNotices(c *gin.Context) (any, error) {
	pq, err := httpx.ParsePage(c)
	if err != nil {
		return nil, err
	}
	f, err := bindNoticeFilter(c)
	if err != nil {
		return nil, err
	}
	q := applyNoticeFilter(scopedNotices(c.Request.Context(), m.db), f)
	var total int64
	if err := q.Session(&gorm.Session{}).Count(&total).Error; err != nil {
		return nil, err
	}
	var rows []noticeRow
	if err := q.Select(noticeColumns).Order("t.id DESC").Offset(pq.Offset()).Limit(pq.PageSize).Scan(&rows).Error; err != nil {
		return nil, err
	}
	views := make([]noticeView, len(rows))
	for i, r := range rows {
		views[i] = r.view()
	}
	return httpx.Page[noticeView]{List: views, Total: total, Page: pq.Page, PageSize: pq.PageSize}, nil
}

var errNoticeNotFound = httpx.NotFound("通知公告不存在")

// loadNotice reads one visible row; rows outside the data scope are 404.
func loadNotice(ctx context.Context, db *gorm.DB, id int64) (noticeView, error) {
	var rows []noticeRow
	if err := scopedNotices(ctx, db).Select(noticeColumns).Where("t.id = ?", id).Scan(&rows).Error; err != nil {
		return noticeView{}, err
	}
	if len(rows) == 0 {
		return noticeView{}, errNoticeNotFound
	}
	return rows[0].view(), nil
}

func (m *Module) getNotice(c *gin.Context) (any, error) {
	id, err := httpx.PathID(c, "id")
	if err != nil {
		return nil, err
	}
	return loadNotice(c.Request.Context(), m.db, id)
}

type noticeRequest struct {
	Title       string           `json:"title" binding:"required,max=128" doc:"标题"`
	Type        int16            `json:"type" doc:"类型"`
	Content     string           `json:"content" binding:"required,max=10000" doc:"内容"`
	Attachments []attachment.Ref `json:"attachments" doc:"附件（上传附件接口返回的 name、url、size）"`
	Version     *int             `json:"version" doc:"编辑时必填，用于乐观锁"`
}

// noticeUniqueFields are the columns with a unique index.
var noticeUniqueFields = []uniqueField{}

// noticeDuplicate reports a unique violation on the form field it concerns.
func noticeDuplicate(constraint string) error {
	return duplicateError(constraint, noticeUniqueFields, "通知公告已存在")
}

func (m *Module) createNotice(c *gin.Context) (any, error) {
	var req noticeRequest
	if err := httpx.BindJSON(c, &req); err != nil {
		return nil, err
	}
	ctx := c.Request.Context()
	if err := checkDict(ctx, m.dict, "notice_type", "type", "类型", req.Type); err != nil {
		return nil, err
	}
	files, err := encodeAttachments(req.Attachments)
	if err != nil {
		return nil, err
	}
	uid := actor.From(ctx).UserID()
	var view noticeView
	err = database.RunTx(ctx, m.db, func(tx *gorm.DB) error {
		var id int64
		err := tx.Raw(`INSERT INTO sys_notices (title, type, content, attachments, created_by, updated_by)
			VALUES (?, ?, ?, ?::jsonb, ?, ?) RETURNING id`,
			req.Title, req.Type, req.Content, files, uid, uid).Scan(&id).Error
		if err != nil {
			if constraint, ok := database.UniqueConstraint(err); ok {
				return noticeDuplicate(constraint)
			}
			return err
		}
		view, err = loadNotice(ctx, tx, id)
		return err
	})
	if err != nil {
		return nil, err
	}
	return view, nil
}

func (m *Module) updateNotice(c *gin.Context) (any, error) {
	id, err := httpx.PathID(c, "id")
	if err != nil {
		return nil, err
	}
	var req noticeRequest
	if err := httpx.BindJSON(c, &req); err != nil {
		return nil, err
	}
	if req.Version == nil {
		return nil, fieldError("version", "不能为空")
	}
	ctx := c.Request.Context()
	if err := checkDict(ctx, m.dict, "notice_type", "type", "类型", req.Type); err != nil {
		return nil, err
	}
	files, err := encodeAttachments(req.Attachments)
	if err != nil {
		return nil, err
	}
	sets := map[string]any{
		"title":       req.Title,
		"type":        req.Type,
		"content":     req.Content,
		"attachments": gorm.Expr("?::jsonb", files),
		"updated_by":  actor.From(ctx).UserID(),
		"updated_at":  gorm.Expr("now()"),
	}
	var view noticeView
	err = database.RunTx(ctx, m.db, func(tx *gorm.DB) error {
		if _, err := loadNotice(ctx, tx, id); err != nil {
			return err
		}
		if err := updateVersioned(tx, noticeTable, id, *req.Version, sets, noticeDuplicate); err != nil {
			return err
		}
		var err error
		view, err = loadNotice(ctx, tx, id)
		return err
	})
	if err != nil {
		return nil, err
	}
	return view, nil
}

func (m *Module) deleteNotice(c *gin.Context) (any, error) {
	id, err := httpx.PathID(c, "id")
	if err != nil {
		return nil, err
	}
	ctx := c.Request.Context()
	return nil, database.RunTx(ctx, m.db, func(tx *gorm.DB) error {
		if _, err := loadNotice(ctx, tx, id); err != nil {
			return err
		}
		err := tx.Exec(`DELETE FROM sys_notices WHERE id = ?`, id).Error
		if database.IsForeignKeyViolation(err) {
			return httpx.Conflict("通知公告已被引用，不能删除")
		}
		return err
	})
}

// encodeAttachments validates request attachments and returns their JSON.
func encodeAttachments(refs []attachment.Ref) (string, error) {
	clean, err := attachment.Validate(refs)
	if err != nil {
		return "", fieldError("attachments", err.Error())
	}
	raw, err := json.Marshal(clean)
	return string(raw), err
}

// decodeAttachments reads the stored JSON; it is written only by
// encodeAttachments, so a decode error yields an empty list.
func decodeAttachments(raw string) []attachment.Ref {
	refs := []attachment.Ref{}
	if raw != "" {
		_ = json.Unmarshal([]byte(raw), &refs)
	}
	return refs
}
